WITH remaining_keys AS (SELECT status FROM payments EXCEPT ALL SELECT status FROM payments WHERE amount BETWEEN 1210 AND 1360), verified AS (SELECT s.* FROM payments s INNER JOIN remaining_keys k ON s.status = k.status) SELECT s.id, s.order_id, s.method, s.paid_at, s.status, (SELECT SUM(x.quantity) FROM order_items x WHERE x.order_id = s.order_id) AS sum_order_item_quantity FROM verified s
